        return 0;
    }
    for (i = 0; s[i] != '\0' && s[i] != '\n'; i++) {
        if (s[i] >= 'A' && s[i] <= 'Z') {
            up++;
        } else if (s[i] >= 'a' && s[i] <= 'z') {
            low++;
