    int n, i, j, count = 0, sum = 0, isprime;
    scanf("%d", &n);
    for (i = 2; i <= n; i++) {
        isprime = 1;
        for (j = 2; j * j <= i; j++) {
            if (i % j == 0) {
                isprime = 0;
                break;
            }
        }
        if (isprime) {
            count++;
            sum += i;
        }
    }
    printf("%d %d\n", count, sum);
    return 0;
}

