#include <stdio.h>

int fib(int n) {
    int i, a = 1, b = 1, c;
    if (n <= 2) {
        return 1;
    }
    for (i = 3; i <= n; i++) {
        c = a + b;
        a = b;
        b = c;
    }
    return b;
}

int main(void) {
    int n;
    scanf("%d", &n);
    printf("%d\n", fib(n));
    return 0;
}

#include <stdio.h>

int is_prime(int n) {
    int i;
    if (n < 2) {
        return 0;
    }
    for (i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return 0;
        }
    }
    return 1;
}

int main(void) {
    int n;
    scanf("%d", &n);
    printf("%s\n", is_prime(n) ? "YES" : "NO");
    return 0;
}

