}

#include <stdio.h>

int reverse_num(int n) {
    int r = 0;
    while (n > 0) {
        r = r * 10 + n % 10;
        n = n / 10;
    }
    return r;
}

int main(void) {
    int n;
    scanf("%d", &n);
    printf("%d\n", reverse_num(n));
