#include <stdio.h>

long long gcd(long long x, long long y) {
    if (x < 0) x = -x;
    if (y < 0) y = -y;
    while (y) {
        long long t = x % y;
        x = y;
        y = t;
    }
    return x;
}

int main(void) {
    long long a, b, c, d;
    scanf("%lld %lld %lld %lld", &a, &b, &c, &d);
    long long num = a * d + c * b;
    long long den = b * d;
    long long g = gcd(num, den);
    if (g == 0) g = 1;
    num /= g;
    den /= g;
    if (den < 0) { num = -num; den = -den; }
    printf("%lld/%lld\n", num, den);
    return 0;
}

