        for (int j = 0; j < c; j++) {
            if (g[i][j] == '*') {
                putchar('*');
            } else {
                int cnt = 0;
                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        if (di == 0 && dj == 0) continue;
                        int ni = i + di, nj = j + dj;
                        if (ni >= 0 && ni < r && nj >= 0 && nj < c && g[ni][nj] == '*') cnt++;
                    }
                }
                putchar('0' + cnt);
            }
        }
        putchar('\n');
    }
    return 0;
}

