#include <stdio.h>

int main(void) {
    int n, k;
    long long freeTime[15];
    scanf("%d %d", &n, &k);
    for (int i = 0; i < k; i++) freeTime[i] = 0;
    double sumWait = 0;
    long long last = 0;
    for (int i = 0; i < n; i++) {
        long long arr, dur;
        scanf("%lld %lld", &arr, &dur);
        int idx = 0;
        for (int j = 1; j < k; j++) {
            if (freeTime[j] < freeTime[idx]) idx = j;
        }
        long long start = arr > freeTime[idx] ? arr : freeTime[idx];
        sumWait += (double)(start - arr);
        freeTime[idx] = start + dur;
        if (freeTime[idx] > last) last = freeTime[idx];
    }
    printf("%.2f\n%lld\n", sumWait / n, last);
    return 0;
}

