#include <stdio.h>

long long gcd(long long a, long long b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    if (b == 0) return a;
    return gcd(b, a % b);
}

int main(void) {
    int n, hasZero = 0;
    long long a[15], g = 0, l = 1;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    for (int i = 0; i < n; i++) {
        g = gcd(g, a[i]);
        if (a[i] == 0) hasZero = 1;
    }
    if (hasZero) {
        l = 0;
    } else {
        for (int i = 0; i < n; i++) {
            long long v = a[i] < 0 ? -a[i] : a[i];
            l = l / gcd(l, v) * v;
        }
    }
    printf("%lld %lld\n", g, l);
    return 0;
}

#include <stdio.h>

int firstFlag = 1;

void emit(long long p, int c) {
    if (!firstFlag) printf("*");
    firstFlag = 0;
    if (c == 1) printf("%lld", p);
    else printf("%lld^%d", p, c);
}

int main(void) {
    long long n;
    scanf("%lld", &n);
    for (long long d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            int c = 0;
            while (n % d == 0) {
                n /= d;
                c++;
            }
            emit(d, c);
        }
    }
    if (n > 1) emit(n, 1);
    printf("\n");
    return 0;
}

#include <stdio.h>

char s[16];
int used[16];
char cur[16];
int n;

void go(int pos) {
    if (pos == n) {
        cur[n] = 0;
        printf("%s\n", cur);
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (i > 0 && s[i] == s[i - 1] && !used[i - 1]) continue;
        used[i] = 1;
        cur[pos] = s[i];
        go(pos + 1);
        used[i] = 0;
    }
}

