    return 0;
}

#include <stdio.h>

long long total[40];

void kth(int n, char from, char to, char aux, long long k) {
    if (n == 0) return;
    long long big = total[n - 1];
    if (k <= big) {
        kth(n - 1, from, aux, to, k);
        return;
    }
    if (k == big + 1) {
        printf("%c->%c\n", from, to);
        return;
    }
    kth(n - 1, aux, to, from, k - big - 1);
}

int main(void) {
    int n;
    long long k;
    scanf("%d %lld", &n, &k);
    total[0] = 0;
    for (int i = 1; i <= n; i++) total[i] = total[i - 1] * 2 + 1;
    printf("%lld\n", total[n]);
    if (k < 1 || k > total[n]) printf("NONE\n");
    else kth(n, 'A', 'C', 'B', k);
    return 0;
}

