#include <stdio.h>

struct Frac {
    long long n, d;
};

long long gcd(long long a, long long b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    struct Frac x, y, r;
    char op;
    scanf("%lld %lld %c %lld %lld", &x.n, &x.d, &op, &y.n, &y.d);
    if (op == '+') {
        r.n = x.n * y.d + y.n * x.d;
        r.d = x.d * y.d;
    } else if (op == '-') {
        r.n = x.n * y.d - y.n * x.d;
        r.d = x.d * y.d;
    } else if (op == '*') {
        r.n = x.n * y.n;
        r.d = x.d * y.d;
    } else {
        r.n = x.n * y.d;
        r.d = x.d * y.n;
    }
    long long g = gcd(r.n, r.d);
    if (g != 0) {
        r.n /= g;
        r.d /= g;
    }
    if (r.d < 0) {
        r.d = -r.d;
        r.n = -r.n;
    }
    if (r.d == 1) printf("%lld\n", r.n);
    else printf("%lld/%lld\n", r.n, r.d);
    return 0;
}

