#include <stdio.h>

long long a[200005], tmp[200005], cnt = 0;

void ms(int l, int r) {
    if (l >= r) return;
    int mid = (l + r) / 2;
    ms(l, mid);
    ms(mid + 1, r);
    int i = l, j = mid + 1, k = l;
    while (i <= mid && j <= r) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            cnt += mid - i + 1;
            tmp[k++] = a[j++];
        }
    }
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= r) tmp[k++] = a[j++];
    for (i = l; i <= r; i++) a[i] = tmp[i];
}

int main(void) {
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    ms(0, n - 1);
    printf("%lld\n", cnt);
    return 0;
}

