char st[1005];
int sp = 0;

int main(void) {
    char s[1005];
    int depth = 0, best = 0, ok = 1;
    scanf("%s", s);
    for (int i = 0; s[i]; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st[sp++] = c;
            depth++;
            if (depth > best) best = depth;
        } else {
            if (sp == 0) {
                ok = 0;
                break;
            }
            char t = st[--sp];
            int good = (t == '(' && c == ')') || (t == '[' && c == ']') || (t == '{' && c == '}');
            if (!good) {
                ok = 0;
                break;
            }
            depth--;
        }
    }
    if (sp != 0) ok = 0;
    if (ok) printf("YES\n%d\n", best);
    else printf("NO\n");
    return 0;
}

#include <stdio.h>

static char sbuf[130][10005];
static int sp = 0;

void parse(const char *s, int *pi, char *out) {
    int len = 0;
    while (s[*pi] && s[*pi] != ']') {
        char c = s[*pi];
        if (c >= 'a' && c <= 'z') {
            out[len++] = c;
            (*pi)++;
        } else if (c >= '0' && c <= '9') {
            int num = 0;
            while (s[*pi] >= '0' && s[*pi] <= '9') {
                num = num * 10 + (s[*pi] - '0');
                (*pi)++;
            }
            if (s[*pi] == '[') (*pi)++;
            sp++;
            parse(s, pi, sbuf[sp]);
            sp--;
            for (int t = 0; t < num; t++) {
                for (int j = 0; sbuf[sp + 1][j]; j++) out[len++] = sbuf[sp + 1][j];
            }
            if (s[*pi] == ']') (*pi)++;
        } else {
            (*pi)++;
        }
    }
    out[len] = 0;
}

int main(void) {
    char s[305];
    int i = 0;
    scanf("%s", s);
    parse(s, &i, sbuf[0]);
    printf("%s\n", sbuf[0]);
    return 0;
}

