#include <stdio.h>
#include <string.h>

int isAl(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

int main(void) {
    char s[1005];
    int len, i = 0;
    if (!fgets(s, sizeof s, stdin)) return 0;
    len = (int)strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r')) s[--len] = 0;
    while (i < len) {
        if (!isAl(s[i])) {
            i++;
            continue;
        }
        int j = i;
        while (j < len && isAl(s[j])) j++;
