            else if (j == 0) cur[0] = cur[0] + row[0];
            else cur[j] = (cur[j - 1] < cur[j] ? cur[j - 1] : cur[j]) + row[j];
        }
    }
    printf("%lld\n", cur[m - 1]);
    return 0;
}

#include <stdio.h>

static long long dp[10005];
#define NONE (-1)

int main(void) {
    int n, W;
    if (scanf("%d %d", &n, &W) != 2) return 0;
    for (int j = 0; j <= W; j++) dp[j] = NONE;
    dp[0] = 0;
    for (int i = 0; i < n; i++) {
        int w, v;
        if (scanf("%d %d", &w, &v) != 2) return 0;
        for (int j = W; j >= w; j--) {
            if (dp[j - w] == NONE) continue;
            long long cand = dp[j - w] + v;
            if (dp[j] == NONE || cand > dp[j]) dp[j] = cand;
        }
    }
    printf("%lld\n", dp[W]);
    return 0;
}

