#include <stdio.h>

static int parent[100005], size_[100005];

static int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;
    for (int i = 1; i <= n; i++) { parent[i] = i; size_[i] = 1; }
    for (int i = 0; i < m; i++) {
        int a, b;
        if (scanf("%d %d", &a, &b) != 2) return 0;
        int ra = find(a), rb = find(b);
        if (ra != rb) {
            if (size_[ra] < size_[rb]) { int t = ra; ra = rb; rb = t; }
            parent[rb] = ra;
            size_[ra] += size_[rb];
        }
    }
    int groups = 0, biggest = 0;
    for (int i = 1; i <= n; i++) {
        if (find(i) == i) {
            groups++;
            if (size_[i] > biggest) biggest = size_[i];
        }
    }
    printf("%d\n%d\n", groups, biggest);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int head[100005], to_[200005], nxt[200005], ec = 0;
static int indeg[100005], queue_[100005];

static void add(int u, int v) {
    to_[ec] = v;
    nxt[ec] = head[u];
    head[u] = ec++;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;
    for (int i = 1; i <= n; i++) head[i] = -1;
    for (int i = 0; i < m; i++) {
        int a, b;
        if (scanf("%d %d", &a, &b) != 2) return 0;
        add(a, b);
        indeg[b]++;
    }
    int tail = 0;
    for (int i = 1; i <= n; i++) if (indeg[i] == 0) queue_[tail++] = i;
    int done = 0;
    for (int h = 0; h < tail; h++) {
        int u = queue_[h];
        done++;
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to_[e];
            if (--indeg[v] == 0) queue_[tail++] = v;
        }
    }
    printf("%s\n", done == n ? "YES" : "NO");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static long long a[2005];

static int cmp(const void *p, const void *q) {
    long long x = *(const long long *)p, y = *(const long long *)q;
    return x < y ? -1 : (x > y ? 1 : 0);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    qsort(a, n, sizeof(long long), cmp);
    long long cnt = 0;
    for (int i = 0; i < n - 2; i++) {
        if (i > 0 && a[i] == a[i - 1]) continue;
        int l = i + 1, r = n - 1;
        while (l < r) {
            long long s = a[i] + a[l] + a[r];
            if (s == 0) {
                cnt++;
                long long lv = a[l], rv = a[r];
                while (l < r && a[l] == lv) l++;
                while (l < r && a[r] == rv) r--;
            } else if (s < 0) l++;
            else r--;
        }
    }
    printf("%lld\n", cnt);
    return 0;
}

#include <stdio.h>

static long long a[305];
static short dp[305][305];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    int best = 2;
    for (int j = 1; j < n; j++) {
        for (int i = 0; i < j; i++) dp[i][j] = 2;
    }
    for (int j = 2; j < n; j++) {
        for (int i = 1; i < j; i++) {
            long long need = 2 * a[i] - a[j];
            int bestk = 0;
            for (int k = 0; k < i; k++) {
                if (a[k] == need && dp[k][i] > bestk) bestk = dp[k][i];
            }
            if (bestk > 0) dp[i][j] = (short)(bestk + 1);
            if (dp[i][j] > best) best = dp[i][j];
        }
    }
    printf("%d\n", best);
    return 0;
}

