#include <stdio.h>
#include <string.h>

static char s[505];
static int pal[505][505];
static int best[505];

int main(void) {
    if (scanf("%500s", s) != 1) return 0;
    int n = (int)strlen(s);
    for (int i = n - 1; i >= 0; i--) {
        for (int j = i; j < n; j++) {
            if (s[i] == s[j] && (j - i < 2 || pal[i + 1][j - 1])) pal[i][j] = 1;
        }
    }
    for (int i = 0; i < n; i++) {
        best[i] = i + 1;
        for (int j = 0; j <= i; j++) {
            if (!pal[j][i]) continue;
            int cand = (j == 0 ? 1 : best[j - 1] + 1);
            if (cand < best[i]) best[i] = cand;
        }
    }
    printf("%d\n", n ? best[n - 1] : 0);
    return 0;
}
